from qiskit import QuantumCircuit

import numpy as np

def period_finding_7_15()->QuantumCircuit:
    """
        Design a quantum circuit to solve the Period Finding Problem (with a = 7,  N = 15), return the Quantum Circuit after measuring.
    """
    n_count = 4
    qc = QuantumCircuit(n_count + 4, n_count)
    qc.h(range(n_count))
    qc.x(n_count)
    qc.x(n_count+1)
    for q in range(n_count):
        qc.append(make_U_a(7, 15, 4, 2**q), [q] + [n_count, n_count+1, n_count+2, n_count+3])
    qc.append(qft_dagger(n_count), range(n_count))
    qc.measure(range(n_count), range(n_count))
    return qc

def make_U_a(a, N, n, power):
    U = QuantumCircuit(n)
    for _ in range(power):
        U = U_a(a, N, n).compose(U)
    return U.to_gate().control(1)

def U_a(a, N, n):
    U = QuantumCircuit(n)
    for i in range(N):
        b = (a * i) % N
        if b < N:
            for j in range(n):
                if (b >> j) & 1:
                    U.x(j)
            for j in range(n):
                if (i >> j) & 1:
                    U.x(j)
    return U

def qft_dagger(n):
    qc = QuantumCircuit(n)
    for j in range(n//2):
        qc.swap(j, n-j-1)
    for j in range(n):
        for m in range(j):
            qc.cp(-np.pi/float(2**(j-m)), m, j)
        qc.h(j)
    return qc

